// Una obligación por proveedor en pagos-tickets-service. Si falla, el flujo responde error y la propuesta queda en ERROR.
const { headers, body: b } = $input.first().json;
if (!$env.N8N_CLAVE || headers['x-clave-comedor'] !== $env.N8N_CLAVE) throw new Error('Clave incorrecta');
for (const p of b.proveedores) {
  await this.helpers.httpRequest({ method: 'POST', url: `${$env.PAGOS_URL}/proveedores/pagos`, json: true,
    body: { ordenId: b.ordenId, proveedor: p.proveedor, monto: p.monto, detalle: p.detalle } });
}
return [{ json: { ok: true, registradas: b.proveedores.length } }];
